-- SecondScreen.lua
L["The game window is only %d × %d pixels. It must span both monitors (main monitor width + %d).%s"] = "Das Spielfenster ist nur %d × %d Pixel groß. Es muss über beide Monitore reichen (Hauptmonitor-Breite + %d).%s"
L["Zone Map"] = "Zonenkarte"
L["The Zone Map cannot be loaded in combat."] = "Die Zonenkarte kann im Kampf nicht geladen werden."
L["Zone Map (Blizzard_BattlefieldMap) could not be loaded."] = "Zonenkarte (Blizzard_BattlefieldMap) konnte nicht geladen werden."
L["The Zone Map is not available here (Blizzard does not show it in every instance, for example)."] = "Die Zonenkarte ist hier nicht verfügbar (Blizzard zeigt sie z. B. nicht in jeder Instanz)."
L["Dual monitor mode on: 3D world on the main monitor."] = "Zwei-Monitor-Modus aktiv: 3D-Welt auf dem Hauptmonitor."
L["Dual monitor mode off."] = "Zwei-Monitor-Modus aus."
